/* Amplify Params - DO NOT EDIT
    API_ATUA_GRAPHQLAPIENDPOINTOUTPUT
    API_ATUA_GRAPHQLAPIIDOUTPUT
    API_ATUA_GRAPHQLAPIKEYOUTPUT
    ENV
    REGION
Amplify Params - DO NOT EDIT */

/* This lambda is for displaying Customer cash collected and Atua share from Cash on Wallet Overview Page*/

/*
 * ==========================================================
 * REQUIRED AWS SDK AND SIGNING LIBRARIES
 * ==========================================================
 *
 * These libraries allow this Lambda to authenticate requests
 * to AWS AppSync using its own IAM execution role.
 *
 * - defaultProvider: Retrieves the Lambda's temporary AWS credentials.
 * - SignatureV4: Signs requests using AWS Signature Version 4.
 * - HttpRequest: Constructs the HTTP request sent to AppSync.
 * - Hash: Provides the SHA-256 hashing implementation required
 *   by the SignatureV4 signer.
 */

const { defaultProvider } = require("@aws-sdk/credential-provider-node");
const { SignatureV4 } = require("@smithy/signature-v4");
const { HttpRequest } = require("@smithy/protocol-http");
const { Hash } = require("@smithy/hash-node");

// --------------------------------------------------
// CONFIGURATION
// --------------------------------------------------

/*
 * AppSync GraphQL API endpoint generated by Amplify.
 * This is where the Lambda sends its GraphQL requests.
 */

const APPSYNC_URL = process.env.API_ATUA_GRAPHQLAPIENDPOINTOUTPUT;

/*
 * AWS region in which the AppSync API and Lambda operate.
 */

const AWS_REGION = process.env.REGION || process.env.AWS_REGION;

/*
 * Pagination settings:
 *
 * PAGE_SIZE:
 * Number of cash collection records requested per GraphQL page.
 *
 * MAX_PAGES:
 * Maximum number of pages this Lambda will retrieve in one request.
 * At 1,000 records per page, this allows up to 20,000 records.
 */

const PAGE_SIZE = 1000;
const MAX_PAGES = 20;

// --------------------------------------------------
// APPSYNC IAM AUTHENTICATION
// --------------------------------------------------

/*
 * Executes a GraphQL query against AppSync using IAM authentication.
 *
 * IMPORTANT:
 * The Lambda uses its IAM execution role to access AppSync.
 * It does not use the courier's Cognito credentials to access
 * the CashCollection model directly.
 *
 * The courier's identity is verified separately before records
 * are retrieved.
 */

async function executeGraphQL(query, variables = {}) {
  // Ensure the AppSync endpoint is configured.
  if (!APPSYNC_URL) {
    throw new Error("AppSync GraphQL endpoint is not configured.");
  }

  // Ensure the AWS region is available.
  if (!AWS_REGION) {
    throw new Error("AWS region is not configured.");
  }

  // Parse the AppSync endpoint URL.
  const endpoint = new URL(APPSYNC_URL);

  // Prepare the GraphQL request body.
  const body = JSON.stringify({
    query,
    variables,
  });

  /*
   * Construct the HTTP request before signing it.
   * The signature proves that this request was made using
   * credentials belonging to an authorized AWS IAM identity.
   */

  const request = new HttpRequest({
    protocol: endpoint.protocol,
    hostname: endpoint.hostname,
    port: endpoint.port ? Number(endpoint.port) : undefined,
    method: "POST",
    path: endpoint.pathname,
    headers: {
      "Content-Type": "application/json",
      host: endpoint.hostname,
    },
    body,
  });

  /*
   * Create the AWS Signature Version 4 signer.
   *
   * service: "appsync" identifies AppSync as the AWS service
   * receiving this signed request.
   *
   * defaultProvider() retrieves the Lambda execution role's
   * temporary credentials automatically.
   */

  const signer = new SignatureV4({
    credentials: defaultProvider(),
    region: AWS_REGION,
    service: "appsync",
    sha256: Hash.bind(null, "sha256"),
  });

  // Sign the request using the Lambda's IAM credentials.
  const signedRequest = await signer.sign(request);

  // Send the signed GraphQL request to AppSync.
  const response = await fetch(APPSYNC_URL, {
    method: "POST",
    headers: signedRequest.headers,
    body,
  });

  // Read the response as text before attempting to parse it.
  const responseText = await response.text();

  let result;

  // Convert the AppSync response into a JavaScript object.
  try {
    result = JSON.parse(responseText);
  } catch (error) {
    console.error("AppSync returned invalid JSON:", responseText);

    throw new Error("AppSync returned an invalid response.");
  }

  // Reject unsuccessful HTTP responses.
  if (!response.ok) {
    console.error("AppSync HTTP error:", response.status, responseText);

    throw new Error("Unable to retrieve cash collection records.");
  }

  // Reject GraphQL errors even if the HTTP response was successful.
  if (result.errors && result.errors.length > 0) {
    console.error("AppSync GraphQL errors:", JSON.stringify(result.errors));

    throw new Error("AppSync could not complete the requested query.");
  }

  // Ensure AppSync returned a data object.
  if (!result.data) {
    throw new Error("AppSync returned no GraphQL data.");
  }

  return result.data;
}

// --------------------------------------------------
// FIND AUTHENTICATED COURIER
// --------------------------------------------------

/*
 * Finds the Courier record associated with the authenticated
 * Cognito user.
 *
 * The Cognito sub is a unique identifier for the authenticated
 * user. We use it to find the matching Courier record.
 *
 * This prevents a courier from supplying another courier's ID
 * and retrieving that courier's cash collection records.
 */

async function getAuthenticatedCourier(sub) {
  const query = `
        query GetCourierByAuthenticatedSub(
            $sub: String!
            $limit: Int
        ) {
            couriersBySub(
                sub: $sub
                limit: $limit
            ) {
                items {
                    id
                    sub
                }
            }
        }
    `;

  // Query the Courier model using the authenticated Cognito sub.
  const data = await executeGraphQL(query, {
    sub,
    limit: 1,
  });

  // Extract the matching courier records.
  const couriers = data?.couriersBySub?.items || [];

  // Return null if no courier account is associated with this user.
  if (couriers.length === 0 || !couriers[0]?.id) {
    return null;
  }

  /*
   * Additional identity verification.
   *
   * Confirm that the returned Courier record actually belongs
   * to the authenticated Cognito user.
   */

  if (couriers[0].sub !== sub) {
    throw new Error("Courier identity verification failed.");
  }

  return couriers[0];
}

// --------------------------------------------------
// GET CASH COLLECTIONS FOR THE COURIER
// --------------------------------------------------

/*
 * Retrieves all CashCollection records belonging to the
 * authenticated courier.
 *
 * The cashCollectionsByCourier query uses the existing
 * courierID index on the CashCollection model.
 *
 * Pagination ensures that couriers with many cash collections
 * can retrieve more than the first page of records.
 *
 * Every returned record is checked again to ensure that its
 * courierID matches the authenticated courier.
 */

async function getCourierCashCollections(courierID) {
  const query = `
        query CashCollectionsByCourier(
            $courierID: ID!
            $limit: Int
            $nextToken: String
        ) {
            cashCollectionsByCourier(
                courierID: $courierID
                limit: $limit
                nextToken: $nextToken
            ) {
                items {
                    id
                    orderID
                    courierID
                    amount
                    status
                    idempotencyKey
                    confirmedAt
                    reconciledAt
                    reconciliationReference
                    courierDebtID
                    atuaShareAmount
                    debtAppliedAt
                    createdAt
                    updatedAt
                }
                nextToken
            }
        }
    `;

  // This array will hold records retrieved from every page.
  const allItems = [];

  // AppSync returns a nextToken when additional records are available.
  let nextToken = null;

  // Tracks the number of pages retrieved.
  let pageCount = 0;

  /*
   * Keep requesting pages until AppSync returns no nextToken.
   */

  do {
    pageCount++;

    // Request the next page of cash collection records.
    const data = await executeGraphQL(query, {
      courierID,
      limit: PAGE_SIZE,
      nextToken,
    });

    // Extract the indexed query result.
    const connection = data?.cashCollectionsByCourier;

    if (!connection) {
      throw new Error("Cash collection query returned no data.");
    }

    // Extract records from the current page.
    const items = connection.items || [];

    /*
     * SECURITY CHECK:
     *
     * Confirm that every record returned by AppSync belongs
     * to the authenticated courier.
     *
     * If even one record belongs to another courier, stop
     * processing rather than returning potentially incorrect data.
     */

    for (const item of items) {
      if (item.courierID !== courierID) {
        throw new Error(
          "A cash collection did not match the authenticated courier.",
        );
      }

      // Add the verified record to the final results.
      allItems.push(item);
    }

    // Store the token needed to retrieve the next page.
    nextToken = connection.nextToken || null;

    /*
     * Prevent an unlimited pagination loop.
     *
     * If more records remain after the maximum number of pages,
     * throw an error rather than returning an incomplete result
     * as though retrieval had succeeded.
     */

    if (nextToken && pageCount >= MAX_PAGES) {
      throw new Error("Maximum cash collection page limit reached.");
    }
  } while (nextToken);

  // Return all verified cash collection records.
  return allItems;
}

// --------------------------------------------------
// MAIN LAMBDA HANDLER
// --------------------------------------------------

/*
 * Main entry point invoked by AppSync when the authenticated
 * courier calls the getMyCashCollections GraphQL query.
 *
 * Overall process:
 *
 * 1. Read the authenticated Cognito identity.
 * 2. Extract the Cognito sub.
 * 3. Find the Courier record belonging to that sub.
 * 4. Retrieve cash collections using the courier's database ID.
 * 5. Return the records to the authenticated frontend.
 *
 * The frontend uses these records to display:
 * - Total customer cash collected.
 * - Total Atua share from cash collections.
 * - Recent cash collection activity.
 *
 * This Lambda only retrieves records. It does not create cash
 * collections, change payment statuses, update courier debts,
 * or modify wallet balances.
 */

exports.handler = async (event) => {
  try {
    console.log("getMyCashCollections invoked.");

    // --------------------------------------------------
    // STEP 1: GET AUTHENTICATED COGNITO IDENTITY
    // --------------------------------------------------

    /*
     * AppSync supplies the authenticated user's identity
     * in event.identity when invoking this Lambda.
     */

    const identity = event?.identity;

    // Extract the unique Cognito user identifier.
    const sub = identity?.sub || identity?.claims?.sub;

    // Reject requests without an authenticated Cognito identity.
    if (!sub) {
      console.warn("Request rejected: no authenticated Cognito sub.");

      return {
        success: false,
        message: "Authentication is required.",
        items: [],
      };
    }

    // --------------------------------------------------
    // STEP 2: FIND THE AUTHENTICATED COURIER
    // --------------------------------------------------

    /*
     * Use the Cognito sub to find the corresponding Courier
     * database record.
     */

    const courier = await getAuthenticatedCourier(sub);

    // Stop if the authenticated user has no Courier record.
    if (!courier) {
      console.warn("No courier record found for authenticated user.");

      return {
        success: false,
        message: "No courier account was found for this user.",
        items: [],
      };
    }

    console.log("Authenticated courier:", courier.id);

    // --------------------------------------------------
    // STEP 3: RETRIEVE THE COURIER'S CASH COLLECTIONS
    // --------------------------------------------------

    /*
     * Retrieve cash collections using the verified Courier ID.
     *
     * The courierID comes from the Courier record found using
     * the authenticated Cognito sub. It is not accepted from
     * the frontend as a query parameter.
     */

    const items = await getCourierCashCollections(courier.id);

    console.log(
      `Retrieved ${items.length} cash collection records for courier ${courier.id}.`,
    );

    // --------------------------------------------------
    // STEP 4: RETURN SUCCESSFUL RESULT
    // --------------------------------------------------

    /*
     * Return the records in the structure expected by the
     * getMyCashCollections GraphQL result type.
     */

    return {
      success: true,
      message: "Cash collections retrieved successfully.",
      items,
    };
  } catch (error) {
    /*
     * Log the actual error for investigation in CloudWatch.
     *
     * Return a generic message to the frontend so internal
     * implementation details are not exposed to the courier.
     */

    console.error("getMyCashCollections failed:", error);

    return {
      success: false,
      message: "Unable to retrieve cash collections at this time.",
      items: [],
    };
  }
};
